#!/usr/bin/env python3
# Convert the Sigma rule's detection logic to a filter over events.log and
# decode any PowerShell encoded command (base64 of UTF-16LE).
import json, base64, re, sys

def sigma_match(ev):
    img = (ev.get("Image") or "").lower()
    cli = ev.get("CommandLine") or ""
    if not img.endswith("powershell.exe"):
        return False
    return (" -enc " in " "+cli+" ") or (" -encodedcommand " in cli.lower()) or (" -e " in " "+cli+" ")

def decode(cli):
    m = re.search(r"-e(?:nc(?:odedcommand)?)?\s+([A-Za-z0-9+/=]{20,})", cli)
    if not m:
        return None
    raw = base64.b64decode(m.group(1))
    try:
        return raw.decode("utf-16-le")
    except UnicodeDecodeError:
        return raw.decode("latin-1")

hits = 0
for line in open("events.log", encoding="utf-8"):
    line = line.strip()
    if not line:
        continue
    ev = json.loads(line)
    if sigma_match(ev):
        hits += 1
        print("MATCH  %s  user=%s" % (ev["UtcTime"], ev["User"]))
        print("  cmd : %s" % ev["CommandLine"][:80])
        payload = decode(ev["CommandLine"])
        if payload:
            print("  decoded payload:")
            for l in payload.splitlines():
                print("    " + l)
print("sigma matches: %d" % hits)
